void CombatFeedback::set_pending_attribute(AttributeType attribute)
{
    this->pending = attribute;
    this->has_pending = true;
}

void CombatFeedback::clear_pending_attribute()
{
    this->pending = AttributeType::NONE;
    this->has_pending = false;
}

void CombatFeedback::record_player_hit(PlayerType *player_ptr, int damage, bool is_melee)
{
    if ((player_ptr == nullptr) || (damage <= 0)) {
        return;
    }

    if (this->events.size() >= MAX_EVENTS) {
        return;
    }

    /*
     * 宣言が無ければ物理へ落とす。**`NONE` にしない**——画面側の表は `NONE` も物理に寄せるが、
     * 「近接で殴られた」と「属性が分からない」を同じ扱いにすると、後で色を分けたくなったときに
     * 元の情報が無い。
     */
    auto attribute = this->pending;
    if (!this->has_pending) {
        attribute = is_melee ? AttributeType::MONSTER_MELEE : AttributeType::NONE;
    }

    this->clear_pending_attribute();

    const auto mhp = std::max(1, static_cast<int>(player_ptr->mhp));
    CombatEvent event;
    event.kind = CombatEventKind::HIT_PLAYER;
    event.attribute = attribute;
    event.y = player_ptr->y;
    event.x = player_ptr->x;
    event.src_y = player_ptr->y;
    event.src_x = player_ptr->x;
    event.intensity = std::clamp(static_cast<float>(damage) / static_cast<float>(mhp), 0.f, 1.f);
    this->events.push_back(event);
}

void CombatFeedback::record_monster_hit(int y, int x, int damage, int max_hp, AttributeType attribute)
{
    // `HENGBAND_FX_LOG` を指したときだけ。「与ダメの演出が出ない」の切り分けの 1 段目。
    if (std::getenv("HENGBAND_FX_LOG") != nullptr) {
        std::fprintf(stderr, "[fx] hit monster at (%d,%d) dam=%d mhp=%d attr=%d\n",
            y, x, damage, max_hp, static_cast<int>(attribute));
    }

    if ((damage <= 0) || (this->events.size() >= MAX_EVENTS)) {
        return;
    }

    CombatEvent event;
    event.kind = CombatEventKind::HIT_MONSTER;
    event.attribute = attribute;
    event.y = y;
    event.x = x;
    event.src_y = y;
    event.src_x = x;
    event.intensity = std::clamp(static_cast<float>(damage) / static_cast<float>(std::max(1, max_hp)), 0.f, 1.f);
    this->events.push_back(event);
}

void CombatFeedback::record_bolt(int src_y, int src_x, int y, int x, AttributeType attribute)
{
    if (this->events.size() >= MAX_EVENTS) {
        return;
    }

    CombatEvent event;
    event.kind = CombatEventKind::BOLT;
    event.attribute = attribute;
    event.y = y;
    event.x = x;
    event.src_y = src_y;
    event.src_x = src_x;
    event.intensity = 1.f;
    this->events.push_back(event);
}

std::vector<CombatEvent> CombatFeedback::take_events()
{
    // **持ち出して空にする。** 残すと `capture` が 10ms ごとに同じ縁を拾い、演出が止まらなくなる。
    return std::exchange(this->events, std::vector<CombatEvent>{});
}

