std::string_view truncate_to_columns(std::string_view str, int columns)
{
    if (columns <= 0) {
        return {};
    }
    int used = 0;
    std::size_t pos = 0;
    while (pos < str.size()) {
        const int w = char_columns(str, pos);
        if ((used + w) > columns) {
            break; //!< 全角が境目に跨るときは**その文字ごと落とす**（半分は化ける）
        }
        used += w;
        pos += char_bytes(str, pos);
    }
    return str.substr(0, pos);
}

std::string pad_to_columns(std::string_view str, int columns, bool left_align)
{
    const auto body = truncate_to_columns(str, columns);
    const int pad = columns - display_width(body);
    std::string out;
    out.reserve(body.size() + static_cast<std::size_t>(pad > 0 ? pad : 0));
    if (!left_align && (pad > 0)) {
        out.append(static_cast<std::size_t>(pad), ' ');
    }
    out.append(body);
    if (left_align && (pad > 0)) {
        out.append(static_cast<std::size_t>(pad), ' ');
    }
    return out;
}

