            report += " / ";
        }
        report += what;
    };

    //! 半角だけ。バイトと桁が一致する側。
    if (display_width("abc") != 3) {
        fail("半角 3 字の桁数が 3 でない");
    }
    if (char_bytes("abc", 0) != 1) {
        fail("半角のバイト数が 1 でない");
    }
    if (next_char("abc", 0) != 1) {
        fail("半角で 1 文字進めない");
    }
    if (prev_char("abc", 2) != 1) {
        fail("半角で 1 文字戻れない");
    }

    /*
     * 全角。**この行のリテラルは内部の符号化で組まれる**ので、
     * SJIS なら 2 バイト・UTF-8 なら 3 バイトになる。どちらでも**桁は 2**。
     * 桁とバイトを別々に見ていることの確認そのものになっている。
     */
    const std::string wide = "あ";
    if (display_width(wide) != 2) {
        fail("全角 1 字の桁数が 2 でない");
    }
    if (char_bytes(wide, 0) != wide.size()) {
        fail("全角 1 字のバイト数が文字列長と合わない");
    }
    if (next_char(wide, 0) != wide.size()) {
        fail("全角で 1 文字進めない");
    }

    /*
     * **1 バイト目だけで見込むバイト数**（キーボードから 1 バイトずつ受ける所の口）。
     * 文字列が手元にある `char_bytes()` と、同じ文字については同じ答えでなければ、
     * 入力の途中で 1 バイト取りこぼす／余計に待つことになる。
     */
    if (bytes_from_lead(static_cast<unsigned char>('a')) != 1) {
        fail("半角の 1 バイト目から見込むバイト数が 1 でない");
    }
    if (bytes_from_lead(static_cast<unsigned char>(wide[0])) != wide.size()) {
        fail("全角の 1 バイト目から見込むバイト数が実際と合わない");
    }

    const std::string mixed = "あa" + wide;
    if (display_width(mixed) != 5) {
        fail("混在の桁数が 5 でない");
    }
    //! **全角の途中で戻らないこと**（1 バイト戻すと化ける所）。
    if (prev_char(mixed, mixed.size()) != (wide.size() + 1)) {
        fail("混在で最後の全角の頭へ戻れない");
    }

    /*
     * 文字の境目。**全角の途中を「境目」と答えてはいけない**
     * （`iskanji2()` の言い換え。カーソルがそこへ止まると化ける）。
     */
    if (!is_char_boundary(mixed, 0) || !is_char_boundary(mixed, wide.size())) {
        fail("文字の頭を境目と認めない");
    }
    if (wide.size() > 1) {
        for (std::size_t i = 1; i < wide.size(); ++i) {
            if (is_char_boundary(mixed, i)) {
                fail("全角の途中を境目と答えている");
                break;
            }
        }
    }
    if (!is_char_boundary(mixed, mixed.size())) {
        fail("末尾を境目と認めない");
    }

    //! 切り詰め。**全角が境目に跨るならその文字ごと落とす。**
    if (display_width(truncate_to_columns(mixed, 4)) != 3) {
        fail("4 桁で切ったのに 3 桁にならない（全角を半分残している）");
    }
    if (truncate_to_columns(mixed, 0) != std::string_view{}) {
        fail("0 桁で空にならない");
    }

    //! 桁揃え。**バイトではなく桁で埋める。**
    const auto padded = pad_to_columns(wide, 6);
    if (display_width(padded) != 6) {
        fail("桁揃えの結果が 6 桁でない");
    }
    if (display_width(pad_to_columns(mixed, 3)) != 3) {
        fail("溢れた桁揃えが 3 桁に収まっていない");
    }

    //! 空・範囲外。**落ちないこと。**
    if ((display_width("") != 0) || (char_bytes("", 0) != 0) || (char_columns("abc", 99) != 0)) {
        fail("空や範囲外で 0 を返さない");
    }
    if (next_char("", 0) != 0) {
        fail("空で進めようとして壊れる");
    }

    /*
     * ここから **UTF-8 の道**（`text::utf8`）。内部がまだ SJIS でも通す。
     * バイト列を直に書くのは、**この build の実行文字コードに左右されないため**。
     * 切り替えてから初めて壊れているのが判るのでは遅いので、先に通しておく。
     */
    {
        const std::string_view u_a = "\xe3\x81\x82"; //!< U+3042「あ」= 3 バイト
        if ((utf8::char_bytes(u_a, 0) != 3) || (utf8::char_columns(u_a, 0) != 2)) {
            fail("UTF-8: かなが 3 バイト 2 桁にならない");
        }
        const std::string_view u_ru = "\xd0\x94"; //!< U+0414「Д」= 2 バイト**だが 1 桁**
        if ((utf8::char_bytes(u_ru, 0) != 2) || (utf8::char_columns(u_ru, 0) != 1)) {
            fail("UTF-8: キリル文字が 2 バイト 1 桁にならない（バイト数で桁を決めている）");
        }
        const std::string_view u_emoji = "\xf0\x9f\x90\x89"; //!< U+1F409 = 4 バイト
        if (utf8::char_bytes(u_emoji, 0) != 4) {
            fail("UTF-8: 4 バイト文字を 4 バイトと数えない");
        }
        //! 漢字（3 バイト 2 桁）＋ ラテン（1 バイト 1 桁）＋ キリル（2 バイト 1 桁）
        const std::string_view u_mixed = "\xe6\xbc\xa2" "a" "\xd0\x94";
        if (u_mixed.size() != 6) {
            fail("UTF-8: 検査用の並びが 6 バイトでない");
        }
        if (utf8::display_width(u_mixed) != 4) {
            fail("UTF-8: 6 バイトの並びが 4 桁にならない（バイト＝桁のまま数えている）");
        }
        //! 途中で切れた並びで**範囲の外を読まない**こと。
        if (utf8::char_bytes(u_a.substr(0, 2), 0) != 2) {
            fail("UTF-8: 切れた並びで残りより多く読もうとする");
        }
        if (utf8::display_width("") != 0) {
            fail("UTF-8: 空が 0 桁にならない");
        }
    }
    return report.empty();
}

