class RealtimeClock {
public:
    static RealtimeClock &get_instance();

    RealtimeClock(const RealtimeClock &) = delete;
    RealtimeClock &operator=(const RealtimeClock &) = delete;

    bool is_enabled() const;
    void set_enabled(bool enables);

    //! 1 行動（通常速度で 10 刻み）あたりの秒数。プレイヤーに見せるのはこちら。
    double get_seconds_per_turn() const;
    void set_seconds_per_turn(double seconds);

    /*!
     * @brief 1 刻みの実時間（ms）。Term 側が締切を作るのに使う。
     * @details **固定値ではない。** 行動するたびに引き直される（`begin_action_stretch`）。
     * 揺らぎと速度差を**世界の拍**へ逃がすことで、自分の足取りを一定に保つため。
     */
    int get_ms_per_tick() const;

    /*!
     * @brief 速さの振れ幅（プレイヤーの設定）。**自分の行動間隔がここまでしか変わらない。**
     * @details 1.0 = 自分の間隔は常に一定で、速度差は全部**世界の拍**に出る（加速＝世界がスロー）。
     * 大きくすると自分も速くなるが、その分だけ操作の拍が変わる。**はみ出た分は必ず世界へ載る**ので、
     * どれを選んでも**ゲームの有利不利は 1 ビットも変わらない**（相対の倍率が保存される）。
     */
    double get_self_speed_span() const;
    void set_self_speed_span(double span);

    /*!
     * @brief 1 回の行動が終わった。次に動けるまでの区間の拍を引き直す。
     * @param ticks_until_ready 次に動けるまでの刻み数（1 以上）
     * @param energy_per_tick 1 刻みで溜まるエネルギー（`speed_to_energy(pspeed)`）
     * @param energy_use その行動の**素の**コスト（100 が普通。揺らぎを掛ける前）
     * @details ここが「揺らぎの行き先を変える」肝である。持ち時間は**揺らぎの無い予定**から
     * 決め、実際にかかった刻み数で割る。こうすると足取りは揃い、揺らぎは世界の拍へ移る。
     */
    void begin_action_stretch(int ticks_until_ready, int energy_per_tick, int energy_use);

    /*!
     * @brief 見送っている間の拍を引き直す（行動が起きないので実刻み数が無いとき）
     * @param energy_per_tick 1 刻みで溜まるエネルギー（`speed_to_energy(pspeed)`）
     * @details `begin_action_stretch` と違い**刻み数を整数へ丸めない**。
     * 丸めると速度によって拍がずれる（+20 で 3.33 刻みを 4 と数えて 2 割速くなった）。
     * 実際に行動しているときは carry があるので平均は合うが、こちらには carry が無い。
     */
    void update_idle_tempo(int energy_per_tick);

    /*!
     * @brief 直前の行動機会を見送ったか
     * @details `process_player` はこれを見て、エネルギーを溜めずに戻る。
     */
    bool is_holding() const;
    void set_holding(bool holds);

    /*!
     * @name 小窓の裏進行（設計書 §7）
     * @details 「いま開いている小窓は裏で世界を進めてよいか」（白名簿）と、
     * 「いま進めている最中か」（再入の歯止め）の 2 つ。
     * **白名簿は既定で閉じている。** 開けるのは、裏で世界が動いても壊れないと
     * 確かめた小窓だけ（いまは持ち物・装備・足元の選択）。
     * @{
     */
    bool is_prompt_background_allowed() const;
    void set_prompt_background_allowed(bool allows);

    /*!
     * @brief プレイヤーが「小窓の裏でも進める」を選んでいるか（`hd2d.cfg` の `realtime_prompt`）
     * @details 白名簿（`prompt_background_allowed`）と**両方**が立ったときだけ裏で進む。
     * 白名簿は「その小窓なら壊れない」という技術の話、こちらは「そう遊びたい」という好みの話で、
     * 別のものである。混ぜると、危ない小窓まで設定 1 つで開いてしまう。
     */
    bool is_prompt_background_wanted() const;
    void set_prompt_background_wanted(bool wants);

    bool is_stepping_world() const;
    void set_stepping_world(bool steps);
    /*! @} */

    /*!
     * @brief 締切を張り直させる
     * @details ロード直後・階の移動・小窓から戻った直後など、実時間が大きく飛んだとき。
     * 張り直さないと、飛んだぶんを取り返そうとして早送りが暴発する。
     */
    void request_resync();
    bool consume_resync();

private:
    RealtimeClock() = default;

    bool enabled{ false };
    double seconds_per_turn{ 1.0 };
