};

/*!
 * @brief いまの言語。
 * @details 既定は日本語。切り替える口は `set_language()` で、
 * 画面側からは `ui_state.lang`、頭が無い時は環境変数 `HENGBAND_LANG` で入る
 * （どちらも `platform/windows/core_main.cpp`）。
 */
inline Language g_language = Language::JAPANESE;

/*!
 * @brief 言語を切り替えた回数。
 * @details 名前空間スコープの表は `set_language()` より先に初期化されるので、
 * 中身を遅らせて持つ器（`locale/localized-table.h`）が「自分は古いか」を
 * これで見分ける。**遊んでいる途中でも切り替わる**（画面から `ui_state.lang` が来る）。
 */
inline int g_language_generation = 0;

inline Language current_language() noexcept
{
    return g_language;
}

inline int language_generation() noexcept
{
    return g_language_generation;
}

inline void set_language(Language language) noexcept
{
    if (g_language == language) {
        return;
    }

    g_language = language;
    ++g_language_generation;
}

inline bool is_japanese() noexcept
{
    return g_language == Language::JAPANESE;
}

