namespace text {

namespace utf8 {

/*!
 * @brief UTF-8 の 1 バイト目から、その文字のバイト数を出す。
 * @details 内部が UTF-8 になったときのための道。**いまは使われない**
 * （`JP` のときは SJIS / EUC で答えるため）が、切り替えを 1 行で済ませるために
 * 先に書いておく。壊れた並びは 1 バイト扱いにして先へ進める。
 */
std::size_t bytes_from_lead(unsigned char lead)
{
    if (lead < 0x80) {
        return 1;
    }
    if ((lead & 0xe0) == 0xc0) {
        return 2;
    }
    if ((lead & 0xf0) == 0xe0) {
        return 3;
    }
    if ((lead & 0xf8) == 0xf0) {
        return 4;
    }
    return 1; //!< 継続バイトや不正な先頭。止まらせない
}

/*!
 * @brief UTF-8 の符号位置が全角か。
 * @details 東アジアの全角（CJK・かな・全角記号・ハングル）を 2 桁とする。
 * キリル・ギリシャ・ラテン拡張は**2 バイトだが 1 桁**——ここが SJIS と決定的に違う。
 */
bool utf8_is_wide(char32_t cp)
{
    return ((cp >= 0x1100) && (cp <= 0x115f)) // ハングル字母
        || ((cp >= 0x2e80) && (cp <= 0x303e)) // CJK 部首・記号
        || ((cp >= 0x3041) && (cp <= 0x33ff)) // かな・注音・ハングル互換・囲み
        || ((cp >= 0x3400) && (cp <= 0x4dbf)) // CJK 拡張 A
        || ((cp >= 0x4e00) && (cp <= 0x9fff)) // CJK 統合漢字
        || ((cp >= 0xa000) && (cp <= 0xa4cf)) // イ文字
        || ((cp >= 0xac00) && (cp <= 0xd7a3)) // ハングル音節
        || ((cp >= 0xf900) && (cp <= 0xfaff)) // CJK 互換漢字
        || ((cp >= 0xfe30) && (cp <= 0xfe6f)) // CJK 互換形・小字形
        || ((cp >= 0xff00) && (cp <= 0xff60)) // 全角英数・記号
        || ((cp >= 0xffe0) && (cp <= 0xffe6)) // 全角通貨記号
        || ((cp >= 0x20000) && (cp <= 0x3fffd)); // CJK 拡張 B 以降
}

char32_t utf8_codepoint(std::string_view str, std::size_t pos, std::size_t len)
{
    const auto at = [&](std::size_t i) { return static_cast<unsigned char>(str[pos + i]); };
    switch (len) {
    case 2:
        return static_cast<char32_t>(((at(0) & 0x1f) << 6) | (at(1) & 0x3f));
    case 3:
        return static_cast<char32_t>(((at(0) & 0x0f) << 12) | ((at(1) & 0x3f) << 6) | (at(2) & 0x3f));
    case 4:
        return static_cast<char32_t>(((at(0) & 0x07) << 18) | ((at(1) & 0x3f) << 12)
            | ((at(2) & 0x3f) << 6) | (at(3) & 0x3f));
    default:
        return static_cast<char32_t>(at(0));
    }
}

std::size_t char_bytes(std::string_view str, std::size_t pos)
{
    if (pos >= str.size()) {
        return 0;
    }
    //! 末尾で切れていたら残りだけ返す（範囲の外を読ませない）。
    return std::min(bytes_from_lead(static_cast<unsigned char>(str[pos])), str.size() - pos);
}

int char_columns(std::string_view str, std::size_t pos)
{
    const auto len = char_bytes(str, pos);
    if (len == 0) {
        return 0;
    }
    return utf8_is_wide(utf8_codepoint(str, pos, len)) ? 2 : 1;
}

