std::size_t char_bytes(const char *str)
{
    if ((str == nullptr) || (*str == '\0')) {
        return 0;
    }
    std::size_t want = 1;
    if (kInternalIsUtf8) {
        want = utf8::bytes_from_lead(static_cast<unsigned char>(*str));
    } else {
#ifdef JP
        if (iskanji(static_cast<unsigned char>(*str))) {
            want = 2;
        }
#endif
    }
    //! NUL で切れていたらそこまで（範囲の外を読ませない）。
    for (std::size_t i = 1; i < want; ++i) {
        if (str[i] == '\0') {
            return i;
        }
    }
    return want;
}

int char_columns(std::string_view str, std::size_t pos)
{
